// TorrentInfoHashEqualFold applies the EqualFold predicate on the "torrent_info_hash" field.
func TorrentInfoHashEqualFold(v string) predicate.BlocklistEntry {
	return predicate.BlocklistEntry(sql.FieldEqualFold(FieldTorrentInfoHash, v))
}

// TorrentInfoHashContainsFold applies the ContainsFold predicate on the "torrent_info_hash" field.
func TorrentInfoHashContainsFold(v string) predicate.BlocklistEntry {
	return predicate.BlocklistEntry(sql.FieldContainsFold(FieldTorrentInfoHash, v))
}

// HasItem applies the HasEdge predicate on the "item" edge.
func HasItem() predicate.BlocklistEntry {
	return predicate.BlocklistEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ItemTable, ItemColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasItemWith applies the HasEdge predicate on the "item" edge with a given conditions (other predicates).
func HasItemWith(preds ...predicate.Item) predicate.BlocklistEntry {
	return predicate.BlocklistEntry(func(s *sql.Selector) {
		step := newItemStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BlocklistEntry) predicate.BlocklistEntry {
	return predicate.BlocklistEntry(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BlocklistEntry) predicate.BlocklistEntry {
	return predicate.BlocklistEntry(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BlocklistEntry) predicate.BlocklistEntry {
	return predicate.BlocklistEntry(sql.NotPredicates(p))
}
